    public static function has(string $name): bool
    {
        return isset(self::OUTLINE[$name]) || isset(self::FILLED[$name]);
    }

    public static function body(string $name): ?string
    {
        return self::OUTLINE[$name] ?? self::FILLED[$name] ?? null;
    }

    public static function isFilled(string $name): bool
    {
        return isset(self::FILLED[$name]);
    }
